mapper.select:
SELECT r.id, r.class_id AS classId, r.problem_id AS problemId, r.submission_a_id AS submissionAId, r.submission_b_id AS submissionBId, r.user_a_id AS userAId, r.user_b_id AS userBId, COALESCE(NULLIF(csa.remark, ''), NULLIF(ua.nickname, ''), ua.username) AS userAName, COALESCE(NULLIF(csb.remark, ''), NULLIF(ub.nickname, ''), ub.username) AS userBName, r.similarity, r.method, r.status, r.created_at AS createdAt FROM plagiarism_report r LEFT JOIN user ua ON ua.id = r.user_a_id LEFT JOIN user ub ON ub.id = r.user_b_id LEFT JOIN class_student csa ON csa.student_id = r.user_a_id AND csa.class_id = r.class_id LEFT JOIN class_student csb ON csb.student_id = r.user_b_id AND csb.class_id = r.class_id WHERE 1 = 1
AND r.class_id = #{classId}
AND r.problem_id = #{problemId}
AND r.status = #{status}
ORDER BY r.similarity DESC, r.id DESC
